// defaultAgent holds the agent to test with, determined in TestMain.
var defaultAgent string

// testBinaryPath holds the path to the CLI binary built once in TestMain.
// All tests share this binary to avoid repeated builds.
var testBinaryPath string

// TestEnv manages an isolated test environment for E2E tests with real agent calls.
type TestEnv struct {
	T       *testing.T
	RepoDir string
	Agent   AgentRunner
}

// getTestBinary returns the path to the shared test binary.
// It panics if TestMain hasn't run (testBinaryPath is empty).
func getTestBinary() string {
	if testBinaryPath == "" {
		panic("testBinaryPath not set - TestMain must run before tests")
	}
	return testBinaryPath
}

// NewTestEnv creates a new isolated E2E test environment.
func NewTestEnv(t *testing.T) *TestEnv {
	t.Helper()

	// Resolve symlinks on macOS where /var -> /private/var
	repoDir := t.TempDir()
	if resolved, err := filepath.EvalSymlinks(repoDir); err == nil {
		repoDir = resolved
	}

	// Create agent runner
	agent := NewAgentRunner(defaultAgent, AgentRunnerConfig{})

	return &TestEnv{
		T:       t,
		RepoDir: repoDir,
		Agent:   agent,
	}
}

// NewFeatureBranchEnv creates an E2E test environment ready for testing.
// It initializes the repo, creates an initial commit on main,
// checks out a feature branch, and sets up agent hooks.
func NewFeatureBranchEnv(t *testing.T, strategyName string) *TestEnv {
	t.Helper()

	env := NewTestEnv(t)
	env.InitRepo()
	env.WriteFile("README.md", "# Test Repository\n\nThis is a test repository for E2E testing.\n")
	env.GitAdd("README.md")
	env.GitCommit("Initial commit")
	env.GitCheckoutNewBranch("feature/e2e-test")

	// OpenCode's `run` (non-interactive) mode defaults external_directory permission
	// to "ask", which auto-rejects since there's no user to prompt — even when the
	// path is the project directory itself. Override to "allow" for the test repo.
	// Note: specific path patterns don't work here because OpenCode evaluates the
	// catch-all "ask" rule before specific "allow" rules (known issue).
	if defaultAgent == AgentNameOpenCode {
		env.WriteFile("opencode.json", `{
  "permission": {
    "external_directory": "allow"
  }
}
`)
	}

	// Use `entire enable` to set up everything (hooks, settings, etc.)
	// This sets up .entire/settings.json and .claude/settings.json with hooks
	env.RunEntireEnable(strategyName)

	// Commit all files created by `entire enable` so they survive git stash -u operations.
	// Without this, stash operations would stash away the hooks config and entire settings,
	// causing hooks to not fire for subsequent prompts and stash pop conflicts.
	// Using "git add ." is safe in test repos since we control all content.
	env.GitAddAll()
	env.GitCommit("Add entire and agent config")

	return env
}

// RunEntireEnable runs `entire enable` to set up the project with hooks.
// Uses the configured defaultAgent (from E2E_AGENT env var or "claude-code").
func (env *TestEnv) RunEntireEnable(strategyName string) {
	env.T.Helper()

	args := []string{
		"enable",
		"--agent", defaultAgent,
		"--strategy", strategyName,
		"--telemetry=false",
		"--force", // Force reinstall hooks in case they exist
	}

	//nolint:gosec,noctx // test code, args are static
	cmd := exec.Command(getTestBinary(), args...)
	cmd.Dir = env.RepoDir

	output, err := cmd.CombinedOutput()
	if err != nil {
		env.T.Fatalf("entire enable failed: %v\nOutput: %s", err, output)
	}
	env.T.Logf("entire enable output: %s", output)
}

